import{p as n}from"./index-DPPgORYe.js";const i=[{slug:"brand-strategy",name:"Brand Strategy",tagline:"Clarity before creation.",heroHeadline:"Strategy that makes every downstream decision obvious.",intro:"Brand strategy is the thinking that happens before any design does. It defines what your company stands for, who it's for, and why it should be chosen over every alternative — in language precise enough to actually drive decisions.",what:"We diagnose where your brand stands and chart the path to where it needs to go. Sharp positioning, a differentiated narrative, and a roadmap to lead your category. Without this foundation, even the most beautiful identity will underperform.",how:"We start with an intensive discovery phase — competitive analysis, audience research, and internal alignment sessions — before developing positioning, messaging hierarchy, and verbal identity. Everything is grounded in evidence and tested against the competitive reality your brand actually faces.",deliverables:["Brand Audit","Qualitative Research","Quantitative Research","Discovery Workshop","Positioning Statement","Brand Architecture","Naming Strategy","Messaging Framework","Verbal Identity","Tone of Voice"],process:[{step:"01",title:"Audit & Research",body:"We examine your existing brand, your competitors, and your target audience — building a factual foundation before any direction is set."},{step:"02",title:"Discovery Workshop",body:"An intensive session with key stakeholders to surface assumptions, align on ambitions, and identify the territory the brand should claim."},{step:"03",title:"Positioning",body:"We develop a positioning that is specific, differentiating, and credible — the one thing your brand should be famous for."},{step:"04",title:"Messaging & Voice",body:"We translate the positioning into a messaging hierarchy and verbal identity — the words, phrases, and principles that govern how the brand communicates."}],featuredProjectIds:["clear-street","phive","flowcase"],faqs:[{q:"Do we need brand strategy before starting design?",a:"In most cases, yes. Strategy defines the problem design is solving. Without it, design becomes subjective — and revisions become endless. Our strategy process typically takes 3–4 weeks and makes every subsequent decision faster and more confident."},{q:"How is brand strategy different from marketing strategy?",a:"Brand strategy defines what you stand for and how you're different — it's the foundation. Marketing strategy defines how you communicate that to specific audiences through specific channels. One informs the other, but they're distinct disciplines."},{q:"Can you do strategy without redesigning our identity?",a:"Absolutely. Sometimes the brand strategy needs refreshing while the visual identity remains strong. We can scope a strategy-only engagement that produces a new positioning and messaging framework without touching the visual side."},{q:"How long does a brand strategy engagement take?",a:"A focused strategy sprint takes 3–5 weeks from kickoff to final deliverables. A deeper engagement that includes research, workshops, and multiple rounds of positioning development typically runs 6–8 weeks."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/a5b674fefa860f0864baaf56bfbc2bb526b263fb-1180x720.jpg"},{slug:"brand-identity",name:"Brand Identity",tagline:"Identity that earns attention.",heroHeadline:"Brands that are unmistakable before a word is read.",intro:"Brand identity is the system of visual elements — logo, typography, colour, motion, and graphic language — that makes a brand immediately and consistently recognisable across every touchpoint.",what:"We design brands that stand apart. Not just logos — complete visual systems built to work at every size, on every surface, in every context. Purpose-built to be distinctive in your specific competitive landscape.",how:"We begin with a thorough competitive audit and positioning alignment before developing visual directions. Every element is chosen for a reason — colour that owns territory in your category, typography that expresses your personality, a logo that survives ten years of daily use.",deliverables:["Logo System","Visual Identity","Typography System","Colour System","Brand Guidelines","Motion Identity","Graphic Language","Art Direction","Iconography","Brand Applications","Verbal Identity"],process:[{step:"01",title:"Strategic Foundation",body:"We align on positioning, audience, and competitive context before picking up a pencil — because every visual decision flows from these answers."},{step:"02",title:"Visual Exploration",body:"We develop 2–3 distinct visual directions, each grounded in a different strategic reading of the brand — not variations of the same idea."},{step:"03",title:"System Development",body:"We build the chosen direction into a full system: type scale, colour architecture, graphic language, motion principles, and application rules."},{step:"04",title:"Handover",body:"Comprehensive brand guidelines, asset files in every format, and a walkthrough session to ensure your team can use the system independently."}],featuredProjectIds:["multiversx","jeton","tuu"],faqs:[{q:"Do you design logos as a standalone service?",a:"We don't design logos in isolation — a mark disconnected from a broader visual system rarely survives contact with real-world application. Every identity engagement produces a complete system that the logo lives within."},{q:"How many logo concepts do we get?",a:"We develop 2–3 distinct visual directions, each grounded in a clear strategic rationale. We find this produces better decisions than presenting 10 concepts — it forces focus on direction rather than surface-level preference."},{q:"What file formats are included in the handover?",a:"All logo files in SVG, EPS, PNG (transparent), and PDF. Full colour codes in HEX, RGB, CMYK, and Pantone. Font licence guidance, pattern and graphic element files, and comprehensive brand guidelines in PDF."},{q:"Can you work with an existing brand we're refreshing?",a:"Yes. Many of our best projects are brand refreshes — preserving what's working while updating what's aged. We'll audit the existing brand to identify what should be retained and what should evolve."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/195dabd5e5757919b90b5d5102a477117981912e-1180x720.jpg"},{slug:"digital-experience",name:"Digital Experience",tagline:"Websites that convert and inspire.",heroHeadline:"Digital products that feel as premium as the brands they represent.",intro:"We design and build websites and digital products that balance craft with performance — creating experiences that reflect the brand's ambition while actually converting the visitors it attracts.",what:"From marketing sites to full product platforms, we design with an understanding that the website is often the brand's most important asset. Every interaction, every transition, every micro-moment is a brand statement.",how:"We work in close collaboration between design and engineering from the very first wireframe. This isn't sequential — it's simultaneous. We design for what's buildable at the quality we require, and we build what would otherwise require compromise to achieve.",deliverables:["Web Design","Web Development","UX Strategy","Interaction Design","Motion Design & 3D","WebGL Development","Design System","Performance Optimisation","CMS Integration","Analytics Setup","Accessibility Audit"],process:[{step:"01",title:"Strategy & Architecture",body:"Audience understanding, sitemap, conversion goals, and technical requirements — before any visual work begins."},{step:"02",title:"UX & Wireframes",body:"Information architecture and wireframes that resolve the hard UX questions before design amplifies them."},{step:"03",title:"Design & Prototyping",body:"High-fidelity designs and interactive prototypes that test the experience before a line of production code is written."},{step:"04",title:"Build & Launch",body:"Engineering that matches the design standard — no compromises, no simplifications. Full QA and performance testing before launch."}],featuredProjectIds:["remote","flecto","care-to-beauty"],faqs:[{q:"Do you build on specific platforms (WordPress, Webflow, etc.)?",a:"We build on the platform that best serves the project's requirements. For marketing sites, that's often Webflow or a headless CMS. For performance-critical or interactive-heavy builds, we work in code (React, Next.js). We always recommend based on what's right for the project, not what's easiest to build."},{q:"Can we add WebGL or 3D to an existing site?",a:"Yes — we approach these as integration projects rather than rebuilds. We assess the existing codebase, identify what's compatible, and design the interactive elements to work within the existing architecture."},{q:"How do you handle SEO during a website rebuild?",a:"SEO is part of our build process from the start — not an afterthought. We audit the existing site's SEO equity, implement redirects to protect ranking pages, build with semantic HTML, and optimise Core Web Vitals."},{q:"What's included in the ongoing relationship after launch?",a:"Our Partnership model includes ongoing support, updates, and growth work. For Sprint engagements, we handover with full documentation and a 30-day support window post-launch."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/51d9e034ae6b13b267034a18f3b0a3d8815d27ef-1180x720.jpg"},{slug:"growth-marketing",name:"Growth Marketing",tagline:"Brand-led growth that compounds.",heroHeadline:"Growth systems that turn your brand into a compounding asset.",intro:"We build the strategies, creative systems, and distribution channels that convert a strong brand into measurable business growth — not a single campaign, but a flywheel.",what:"Growth marketing at Beyond means brand-led growth. We connect the dots between brand strategy and growth metrics — building the creative and distribution systems that translate brand quality into acquisition, retention, and revenue expansion.",how:"We begin with a growth audit to identify where the biggest leverage is: is it paid acquisition creative that doesn't match the brand? An SEO opportunity being ignored? A retention problem caused by messaging misalignment? The answer shapes where we focus.",deliverables:["Growth Strategy","Performance Creative","SEO Strategy","Content Strategy","Email Marketing","Social Strategy","Paid Media Creative","Go-to-Market Planning","Analytics & Attribution","Landing Page Optimisation"],process:[{step:"01",title:"Growth Audit",body:"We analyse your current acquisition, activation, retention, and referral metrics to identify where the biggest leverage lives."},{step:"02",title:"Strategy Development",body:"A prioritised growth plan that aligns channel investment with brand positioning and business objectives."},{step:"03",title:"Creative Production",body:"Brand-consistent creative assets built for performance — ads, landing pages, email sequences, and social content."},{step:"04",title:"Iteration",body:"Continuous testing, optimisation, and reporting — built into the process, not bolted on afterwards."}],featuredProjectIds:["phive","clear-street","care-to-beauty"],faqs:[{q:"Is growth marketing only for large companies?",a:"No. Some of our most impactful growth work has been with early-stage companies — establishing the right acquisition channels before spending accelerates. Getting the strategy right early is far cheaper than correcting it after significant spend."},{q:"Do you run paid media campaigns?",a:"We produce the creative strategy and assets for paid media, and we can advise on channel and budget allocation — but we don't act as a paid media buying agency. We work in partnership with your internal team or media agency."},{q:"How do brand and growth work together?",a:"Brand creates the conditions in which growth is more efficient. A strong brand converts better from every paid channel, retains customers longer, and generates referrals that no budget can replicate. Growth marketing without brand investment optimises the tap while leaving the pipe leaking."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/2405f85e088f3e9b8a28f8c364fa64a88c75bff5-1180x720.jpg"},{slug:"content-creative",name:"Content & Creative",tagline:"Content that earns its place.",heroHeadline:"Creative production that doesn't feel like production.",intro:"We produce photography, video, copy, and creative assets that carry a brand forward — not content for content's sake, but the material that makes every touchpoint feel intentional and on-brand.",what:"Content is where brand strategy meets lived experience. We produce the assets that make a brand real: the photography that sets the visual tone, the video that tells the story, the copy that sounds unmistakably like you.",how:"Every content engagement starts with a creative brief that extends from the brand strategy — ensuring that what we produce is directionally correct before production begins. We direct, produce, and deliver at the standard the brand requires.",deliverables:["Brand Photography","Video Production","Copywriting","Social Content","Campaign Production","CGI & 3D Visualisation","Editorial Design","Art Direction","Sound Design","Content Strategy"],process:[{step:"01",title:"Creative Brief",body:"We develop a clear brief that connects the content requirement to the brand strategy — before any production begins."},{step:"02",title:"Pre-production",body:"Storyboards, shot lists, talent casting, location scouting, and prop selection — every detail resolved in advance."},{step:"03",title:"Production",body:"Photography, film, and audio production to the brief — with active creative direction throughout."},{step:"04",title:"Post & Delivery",body:"Editing, colour grading, retouching, and delivery in every format required for digital and print use."}],featuredProjectIds:["floema","phive","kozowood"],faqs:[{q:"Do you produce photography and video in-house?",a:"We co-produce with a vetted network of photographers, directors, and production partners — always under our creative direction. This gives us access to specialist talent without the overhead of a full in-house production team."},{q:"Can you produce CGI and 3D assets?",a:"Yes. We produce CGI product visualisations, 3D brand elements, and animation — all built to integrate with the broader brand system."},{q:"Do you write brand copy and website copy?",a:"Yes. Our copywriting work covers brand messaging, website copy, campaign concepts, and ongoing content strategy. All copy is written within the verbal identity we've established (or audited) for the brand."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/43d9fe391c3de48c4f41dee41fd3a8c97f6540fa-1180x720.jpg"},{slug:"brand-strategy-for-fintech",name:"Brand Strategy for Fintech",tagline:"Strategy built for the complexity of financial services.",heroHeadline:"Brand strategy that builds trust in a trust-sensitive category.",intro:"Fintech brands face a unique challenge: they need to feel innovative enough to disrupt the incumbents, but credible enough to be trusted with money. Brand strategy is what resolves that tension.",what:"We help fintech companies articulate a position that is genuinely differentiated — not just 'simpler banking' or 'the future of finance', phrases that have lost all meaning in the category. Positioning grounded in what you actually do better, for whom, and why.",how:"We combine deep competitive research across the fintech landscape with positioning work that identifies the whitespace your brand can credibly claim. The output is a strategy that drives consistency from investor deck to product interface.",deliverables:["Brand Audit","Competitive Positioning","Audience Research","Positioning Statement","Messaging Framework","Tone of Voice"],process:[{step:"01",title:"Category Mapping",body:"We map the full competitive landscape — established players and emerging challengers — to identify where the real positioning opportunities exist."},{step:"02",title:"Audience Research",body:"Both the end user and the institutional buyer matter in fintech. We develop positioning that speaks credibly to both."},{step:"03",title:"Positioning Development",body:"We develop and pressure-test a positioning specific enough to be ownable and broad enough to grow into."},{step:"04",title:"Messaging Framework",body:"A structured messaging hierarchy that enables consistent communication across every audience, channel, and context."}],featuredProjectIds:["clear-street","jeton","speedy"],faqs:[{q:"How does fintech brand strategy differ from other sectors?",a:"Fintech brands must balance innovation signalling with trust signalling — getting either wrong is costly. The strategy work is more demanding because the audience has higher stakes: they're trusting you with their money."},{q:"Do you work with regulated financial companies?",a:"Yes. We understand the compliance constraints that affect messaging in regulated sectors and factor them into the strategy from the outset."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/a5b674fefa860f0864baaf56bfbc2bb526b263fb-1180x720.jpg",parentService:"brand-strategy",industryName:"Fintech"},{slug:"brand-identity-for-fintech",name:"Brand Identity for Fintech",tagline:"Visual systems built for financial credibility.",heroHeadline:"Fintech brands that look as credible as they are innovative.",intro:"The fintech category is visually homogeneous — navy blues, clean sans-serifs, stock photography of phones and cards. Breaking that pattern requires a visual identity grounded in genuine strategic differentiation.",what:"We design fintech brand identities that are distinctly positioned within their competitive landscape — not just polished versions of the category norm. Every element of the system communicates the brand's specific claim to be different.",how:"Our process begins with an audit of the visual language across the competitive fintech landscape — identifying what's overused, what's underutilised, and what represents a credible space for your brand to own. Then we design to claim it.",deliverables:["Logo System","Visual Identity","Typography System","Colour System","Brand Guidelines","Motion Identity","App Icon","Marketing Templates"],process:[{step:"01",title:"Category Audit",body:"A thorough audit of the visual conventions and clichés in your specific fintech category."},{step:"02",title:"Visual Exploration",body:"2–3 distinct visual directions, each claiming a different positioning territory."},{step:"03",title:"System Development",body:"Full identity system built for fintech's specific needs: digital-first, compliant, scalable across product and marketing."},{step:"04",title:"Handover",body:"All brand assets, guidelines, and templates in every format — including app icon files and digital-specific specs."}],featuredProjectIds:["clear-street","jeton","speedy"],faqs:[{q:"Do you have experience with regulated brand applications?",a:"Yes. We factor compliance requirements (advertising standards, disclosure requirements) into the brand guidelines from the outset — so the team applying the brand doesn't run into problems later."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/d6d6c1faeb3ec1d1251a2061cd90af8e40b65b5f-1180x720.jpg",parentService:"brand-identity",industryName:"Fintech"},{slug:"brand-identity-for-saas",name:"Brand Identity for SaaS",tagline:"Identity systems built to scale with your product.",heroHeadline:"SaaS brands that feel as good as the product they represent.",intro:"SaaS brand identity has to do two jobs simultaneously: attract the right buyers from the homepage, and feel credible and trustworthy inside the product every single day. That demands a system, not just a mark.",what:"We design SaaS brand identities that span marketing and product — visual systems coherent enough to work on a billboard and precise enough to inform a dashboard component. The identity and the product UI speak the same visual language.",how:"We approach SaaS identity projects with a product-first lens — understanding the product's function, the user's daily context, and the brand's competitive position before any visual direction is set.",deliverables:["Logo System","Visual Identity","Typography System","Colour System","Brand Guidelines","Design System Foundations","Illustration System","Motion Identity"],process:[{step:"01",title:"Product & Market Audit",body:"Understanding the product's UX context and the competitive visual landscape before setting any direction."},{step:"02",title:"Visual Exploration",body:"Identity directions that work across marketing and product — not just on the homepage."},{step:"03",title:"System Build",body:"A full identity system with design tokens ready to be implemented across the product codebase."},{step:"04",title:"Handover & Integration",body:"Comprehensive guidelines plus a handover session with your engineering team on token implementation."}],featuredProjectIds:["flecto","flowcase","remote"],faqs:[{q:"Can you help align our product UI with a new brand identity?",a:"Yes. We can scope product UI alignment work alongside the identity project — ensuring the brand and the product feel like they came from the same hand."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/9883cbd8d50401a2779a8fe4843e99ef8fef9f19-1180x720.jpg",parentService:"brand-identity",industryName:"SaaS"},{slug:"brand-identity-for-web3",name:"Brand Identity for Web3",tagline:"Identity for the next generation of the internet.",heroHeadline:"Web3 brands that attract believers and convert sceptics.",intro:"Web3 brand identity has to bridge two worlds: it needs to resonate with the native crypto community while building the mainstream credibility that mass adoption requires. Getting the balance wrong loses both audiences.",what:"We design web3 brand identities that are genuinely distinctive within the category — moving beyond the defaults of gradient blues, abstract spheres, and uppercase maximalism toward visual systems that carry the brand's specific worldview.",how:"Web3 is a category in rapid visual evolution. We track what's becoming cliché and design against it — building identities that feel ahead of the curve without alienating the community.",deliverables:["Logo System","Visual Identity","Typography System","Colour System","NFT Brand Guidelines","Motion Identity","Token Design","Community Assets"],process:[{step:"01",title:"Community & Market Research",body:"Understanding your specific positioning in the web3 landscape — DeFi, NFT, infrastructure, or consumer app — shapes every visual decision."},{step:"02",title:"Visual Exploration",body:"Identity directions that feel native to web3 while being mainstream-accessible."},{step:"03",title:"System Development",body:"Full identity system including on-chain asset specifications, community guidelines, and token design."},{step:"04",title:"Handover",body:"All brand assets plus community governance guidelines for how the identity should be applied by community contributors."}],featuredProjectIds:["multiversx","talent-protocol"],faqs:[{q:"Can you design for DAOs and community-governed projects?",a:"Yes. We've built community-focused brand systems that include governance guidelines for how community contributors can apply the brand — without requiring central approval for every application."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/195dabd5e5757919b90b5d5102a477117981912e-1180x720.jpg",parentService:"brand-identity",industryName:"Web3"},{slug:"brand-identity-for-startups",name:"Brand Identity for Startups",tagline:"First impressions that open doors.",heroHeadline:"A startup brand that punches far above its weight.",intro:"Early-stage companies face a specific problem: they need to look and feel credible to attract talent, customers, and investors — before they've had time to build the track record that would otherwise create that credibility. Brand is how you bridge the gap.",what:"We build startup brand identities that project conviction and craft — giving early-stage companies the visual authority to compete with established players for the right customers, employees, and capital.",how:"We work quickly without sacrificing quality. Our Sprint model is designed for startups: a focused 6-week engagement that delivers a complete brand system without the timeline of a full agency partnership.",deliverables:["Logo System","Visual Identity","Typography System","Colour System","Brand Guidelines","Pitch Deck Templates","Social Templates","Website Design Direction"],process:[{step:"01",title:"Positioning Alignment",body:"A rapid but rigorous alignment session to define the brand's specific claim and competitive position."},{step:"02",title:"Visual Exploration",body:"Fast, focused visual development — 2 directions, clear feedback loop, decisive selection."},{step:"03",title:"System Build",body:"Complete brand system in 3 weeks — mark, type, colour, graphic language, and core templates."},{step:"04",title:"Handover",body:"Everything your team needs to apply the brand independently from day one."}],featuredProjectIds:["flowcase","grabgo","redacted"],faqs:[{q:"We're pre-revenue — is it too early to invest in brand?",a:"It depends on what you need brand for. If you're raising a seed round or hiring your first 10 people, a strong brand opens doors. If you're still validating the core product, a lightweight brand is fine until you've found product-market fit."},{q:"Can we scale the brand later without starting over?",a:"We design startup brand systems to scale — the foundations are built to support expansion into new products, markets, and sub-brands without requiring a full rebrand every time."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/48a694fb13bbd8b3c37037aecfdce3ac244b953c-1080x1080.jpg",parentService:"brand-identity",industryName:"Startups"},{slug:"digital-experience-for-fintech",name:"Digital Experience for Fintech",tagline:"Fintech websites that build trust and convert.",heroHeadline:"Fintech digital experiences that work as hard as the product.",intro:"A fintech website has one primary job: convert a sceptical visitor into a confident prospect. That requires a website that communicates the product's value, addresses the trust deficit, and moves people through the funnel without friction.",what:"We design and build fintech websites that balance the premium feel of a forward-thinking financial brand with the functional clarity that converts regulated-product visitors into qualified leads.",how:"We approach fintech website projects with conversion in mind from the first wireframe — not as an afterthought. Information architecture, messaging hierarchy, and interaction design all serve the conversion goal.",deliverables:["Website Strategy","UX Design","Visual Design","Web Development","Motion & Interaction","CMS Integration","Analytics Setup","A/B Testing Framework"],process:[{step:"01",title:"Conversion Strategy",body:"Defining the conversion goal, the audience journey, and the content hierarchy before visual work begins."},{step:"02",title:"UX & Architecture",body:"Sitemap, wireframes, and information hierarchy — resolving the hard structural decisions before design."},{step:"03",title:"Design & Interaction",body:"Visual design and interactive prototypes that reflect the brand's quality and guide visitors toward conversion."},{step:"04",title:"Build & Optimise",body:"Production build with performance optimisation, analytics, and a testing framework for post-launch improvement."}],featuredProjectIds:["clear-street","jeton","speedy"],faqs:[{q:"Do you build for regulatory compliance (GDPR, accessibility)?",a:"Yes. We build to WCAG 2.1 AA accessibility standards, implement GDPR-compliant analytics and cookie consent, and advise on financial services advertising compliance."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/d6d6c1faeb3ec1d1251a2061cd90af8e40b65b5f-1180x720.jpg",parentService:"digital-experience",industryName:"Fintech"},{slug:"digital-experience-for-saas",name:"Digital Experience for SaaS",tagline:"SaaS websites built for trial conversion.",heroHeadline:"The SaaS website that finally matches the product.",intro:"Most SaaS marketing sites underperform the product they're promoting. They use generic language, stock imagery, and category-standard design that fails to convey what makes the product genuinely different. We fix that.",what:"We design SaaS websites that communicate the product's specific value proposition with clarity, build category credibility, and convert visitors into trial users — the metric that matters.",how:"We combine product understanding, conversion-focused UX, and brand-aligned visual design to produce SaaS websites that are both beautiful and effective. The two are not in tension when design and strategy work together.",deliverables:["Website Strategy","UX Design","Visual Design","Product Screenshot Design","Web Development","Performance Optimisation","CMS Setup","Analytics"],process:[{step:"01",title:"Product & Audience Deep Dive",body:"Understanding the product thoroughly before designing anything — so the website reflects what makes it genuinely valuable."},{step:"02",title:"Messaging & Wireframes",body:"Conversion-focused messaging hierarchy and UX wireframes before visual design begins."},{step:"03",title:"Design",body:"Visual design that makes the product feel premium, credible, and distinctly positioned in the market."},{step:"04",title:"Build & Launch",body:"Production build with trial CTA optimisation, analytics, and an onboarding-aligned structure."}],featuredProjectIds:["flecto","flowcase","remote"],faqs:[{q:"Can you help us show the product without screenshots?",a:"Yes. We often design illustrated or diagrammatic product representations that convey the value and experience without requiring access to production screens."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/9883cbd8d50401a2779a8fe4843e99ef8fef9f19-1180x720.jpg",parentService:"digital-experience",industryName:"SaaS"},{slug:"digital-experience-for-ecommerce",name:"Digital Experience for E-commerce",tagline:"E-commerce that sells and delights.",heroHeadline:"E-commerce experiences where brand drives conversion.",intro:"E-commerce brands that invest in design consistently outperform those that don't — lower acquisition costs, higher average order values, and better retention. The product experience is the brand experience.",what:"We design e-commerce experiences that are as beautiful to browse as they are frictionless to purchase — understanding that in commerce, visual quality is a direct driver of commercial performance.",how:"We work at the intersection of brand design and UX — ensuring the e-commerce experience carries the brand's visual authority while optimising the path from product discovery to checkout.",deliverables:["UX Strategy","Visual Design","E-commerce UX","Product Page Design","Navigation Design","Mobile Optimisation","Performance Optimisation","Photography Direction"],process:[{step:"01",title:"Customer Journey Mapping",body:"Understanding the full e-commerce customer journey — discovery, comparison, consideration, checkout, return — before designing any single screen."},{step:"02",title:"Navigation & Architecture",body:"Information architecture that makes finding products intuitive and browsing enjoyable."},{step:"03",title:"Design System",body:"A component system built for product scale — works as well for 10 SKUs as for 10,000."},{step:"04",title:"Optimisation",body:"Post-launch performance monitoring, A/B testing, and conversion optimisation."}],featuredProjectIds:["care-to-beauty","floema"],faqs:[{q:"Which e-commerce platforms do you design for?",a:"We design for Shopify, WooCommerce, and custom builds. Platform choice depends on the project's complexity and requirements — we advise based on what's right for your scale and budget."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/7a93219d8ac5acd8c5751d81302f153f62499d84-1180x720.jpg",parentService:"digital-experience",industryName:"E-commerce"},{slug:"brand-strategy-for-startups",name:"Brand Strategy for Startups",tagline:"Position fast. Grow with conviction.",heroHeadline:"The brand foundation that makes everything else more effective.",intro:"Startups without a clear brand strategy waste resources on marketing that doesn't compound. Every campaign, every hire, every investor conversation is harder when the brand's positioning isn't sharp. We fix the foundation.",what:"We develop startup brand strategies that are specific enough to drive decisions — not broad mission statements that could belong to any company, but a positioning precise enough to use as a filter for every subsequent choice.",how:"We move quickly. A sprint-format strategy engagement gets you from unclear positioning to a documented brand strategy in 3–4 weeks — fast enough to keep up with the pace of a scaling company.",deliverables:["Brand Audit","Competitive Research","Positioning Statement","Brand Architecture","Messaging Framework","Tone of Voice","Naming Review"],process:[{step:"01",title:"Discovery",body:"Fast, focused discovery: competitive landscape, audience assumptions, and internal alignment."},{step:"02",title:"Positioning Workshop",body:"An intensive session with founders and key stakeholders to surface the brand's true differentiation."},{step:"03",title:"Positioning Development",body:"Developing and pressure-testing the positioning statement and messaging hierarchy."},{step:"04",title:"Documentation",body:"A concise, actionable brand strategy document — not a 60-page deck no one reads."}],featuredProjectIds:["flowcase","grabgo","keikku"],faqs:[{q:"Should we do brand strategy before or after product-market fit?",a:"After. Brand strategy is most powerful when it's anchoring something real — a product with a clear value proposition and early customer proof. Before PMF, a lightweight positioning hypothesis is sufficient."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/48a694fb13bbd8b3c37037aecfdce3ac244b953c-1080x1080.jpg",parentService:"brand-strategy",industryName:"Startups"},{slug:"growth-marketing-for-saas",name:"Growth Marketing for SaaS",tagline:"SaaS growth that compounds.",heroHeadline:"The growth system your SaaS brand has been missing.",intro:"SaaS growth at scale requires brand and performance working together — not as separate departments with separate budgets, but as a unified system where brand investment makes performance more efficient.",what:"We build growth systems for SaaS companies: the creative, the content, the SEO, and the lifecycle marketing that converts awareness into trials and trials into retained revenue.",how:"We start where the leverage is — auditing your current funnel, identifying the biggest gaps, and prioritising the interventions that will have the most impact on the metrics that matter.",deliverables:["Growth Audit","SEO Strategy","Content Strategy","Performance Creative","Email Lifecycle","Landing Page Optimisation","Social Strategy","Analytics Framework"],process:[{step:"01",title:"Funnel Audit",body:"Where are you losing people? We map the full SaaS funnel — from awareness to activation to retention — and identify the biggest gaps."},{step:"02",title:"Growth Strategy",body:"A prioritised growth plan focused on the highest-leverage interventions given your current stage and resources."},{step:"03",title:"Creative & Systems Build",body:"Producing the creative assets and marketing systems that execute the strategy."},{step:"04",title:"Test & Iterate",body:"Continuous testing, reporting, and optimisation — building the feedback loop into the process."}],featuredProjectIds:["flecto","remote"],faqs:[{q:"Do you handle PLG (product-led growth) strategies?",a:"Yes. We understand the specific dynamics of PLG — where the product is the primary growth mechanism — and design brand and content strategies that complement rather than compete with the product's self-serve model."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/28820f9c8e82e134dc7dd7d7e403da3559edcb62-1080x1080.jpg",parentService:"growth-marketing",industryName:"SaaS"},{slug:"brand-identity-for-healthcare",name:"Brand Identity for Healthcare",tagline:"Healthcare brands that patients and professionals trust.",heroHeadline:"Healthcare identity that earns the trust the category demands.",intro:"Healthcare brands carry the highest trust burden of any category. Patients, clinicians, and institutions must all believe in what you represent — and visual identity is often the first signal they receive.",what:"We design healthcare brand identities that communicate clinical credibility and human warmth simultaneously — rejecting the cold sterility of dated medical design without sacrificing the authority the context requires.",how:"Healthcare identity requires exceptional rigour in the research and strategy phase — understanding regulatory constraints, the full audience landscape (patients, clinicians, administrators, investors), and the competitive visual environment before any creative direction is set.",deliverables:["Logo System","Visual Identity","Typography System","Colour System","Brand Guidelines","Patient-Facing Templates","Clinical Presentation Templates","Motion Identity"],process:[{step:"01",title:"Healthcare Landscape Audit",body:"Deep analysis of the visual conventions and trust signals in your specific healthcare category."},{step:"02",title:"Audience Mapping",body:"Understanding the distinct trust needs of every audience the brand must reach — patients, clinicians, and institutions may require different emphasis."},{step:"03",title:"Visual Development",body:"Identity directions that balance clinical authority with human accessibility."},{step:"04",title:"System Build",body:"Complete identity system with specific guidance for patient-facing and clinical-facing applications."}],featuredProjectIds:["hematogenix","keikku"],faqs:[{q:"Do you understand FDA/CE marking and regulatory constraints?",a:"We understand the general landscape of healthcare marketing regulation and factor it into the brand guidelines. We always recommend working with your regulatory team to review specific applications."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/a2cdc528da6a57c2b6bbefdd87d628763e338bcc-1180x720.jpg",parentService:"brand-identity",industryName:"Healthcare"},{slug:"digital-experience-for-web3",name:"Digital Experience for Web3",tagline:"Web3 sites built for believers and newcomers alike.",heroHeadline:"Web3 digital experiences that convert the curious into the committed.",intro:"Web3 products face a UX challenge unlike any other category: explaining genuinely new concepts, building trust around unfamiliar technology, and creating onboarding flows that work for both crypto-native users and complete newcomers.",what:"We design web3 digital experiences that are visually distinctive, technically excellent, and genuinely usable — for your core community and the broader audience you're trying to grow into.",how:"We combine deep category knowledge with strong UX fundamentals — building interfaces that don't assume prior knowledge while remaining credible to native users who would see condescension immediately.",deliverables:["Website Design","Web Development","WebGL & 3D","Motion Design","Wallet Integration UX","Onboarding Flow Design","Community Portal Design"],process:[{step:"01",title:"Audience Spectrum Mapping",body:"Understanding the full spectrum of your audience — from crypto-native to crypto-curious — and designing for the full range."},{step:"02",title:"Technical Architecture",body:"Defining the tech stack and integrations (wallet connect, chain data, real-time feeds) before design begins."},{step:"03",title:"Design & Interaction",body:"Visual design and interactive prototypes with the full category context — not generic web3 clichés."},{step:"04",title:"Build",body:"Production build with the WebGL, animation, and wallet integration quality the category demands."}],featuredProjectIds:["multiversx","talent-protocol"],faqs:[{q:"Can you integrate wallet connection and on-chain data?",a:"Yes. We work with web3 engineers to design and implement wallet connection flows, on-chain data display, and smart contract interaction UX."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/644ae8d8c5615611ab907c19e78900ba1ebf3da6-1180x720.jpg",parentService:"digital-experience",industryName:"Web3"},{slug:"growth-marketing-for-fintech",name:"Growth Marketing for Fintech",tagline:"Regulated-channel growth that builds trust at scale.",heroHeadline:"Fintech growth that navigates compliance and converts.",intro:"Growth marketing in fintech operates within constraints that other categories don't face: advertising restrictions, compliance requirements, and a trust barrier that takes longer to overcome. Strategy that ignores these constraints produces expensive mistakes.",what:"We build fintech growth strategies that work within regulatory constraints, build trust systematically, and produce the kind of compounding growth that comes from brand and performance working together.",how:"We begin with a compliance-aware growth audit — mapping what channels and claims are available to you — and build a growth strategy around the genuine opportunities that exist, not hypothetical ones.",deliverables:["Growth Audit","Compliance-Aware Strategy","Performance Creative","Content & SEO Strategy","Email Lifecycle","Influencer & Partnership Strategy","Analytics"],process:[{step:"01",title:"Compliance Audit",body:"Understanding the specific advertising and marketing regulations that apply to your fintech product before planning any channel strategy."},{step:"02",title:"Channel Analysis",body:"Identifying the highest-leverage growth channels within your regulatory and budget constraints."},{step:"03",title:"Creative Strategy",body:"Brand-aligned performance creative that converts within the compliance guardrails."},{step:"04",title:"Systems Build",body:"Email lifecycle, content, and paid media systems built for sustainable, measurable growth."}],featuredProjectIds:["clear-street","speedy","jeton"],faqs:[{q:"Can you help with App Store marketing for fintech apps?",a:"Yes. App Store optimisation, app preview design, and mobile acquisition creative are all within our remit — factoring in the specific review guidelines for financial applications."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/d6d6c1faeb3ec1d1251a2061cd90af8e40b65b5f-1180x720.jpg",parentService:"growth-marketing",industryName:"Fintech"},{slug:"brand-identity-for-ecommerce",name:"Brand Identity for E-commerce",tagline:"E-commerce brands that people choose and return to.",heroHeadline:"The brand identity that makes customers choose you again.",intro:"In a world where e-commerce products are increasingly commoditised, brand is the primary driver of preference, loyalty, and word-of-mouth. The brands that grow without burning through acquisition budgets are the ones with genuine visual and emotional distinctiveness.",what:"We design e-commerce brand identities that are premium, distinctive, and built for the full channel mix — from homepage hero to product packaging to social ad to unboxing experience.",how:"E-commerce brand identity design starts with understanding the customer's full journey — from the first Instagram impression to the post-purchase moment — and designing a system that maintains brand cohesion at every touchpoint.",deliverables:["Logo System","Visual Identity","Typography System","Colour System","Packaging Design Direction","Social Asset Templates","Brand Guidelines","Photography Direction"],process:[{step:"01",title:"Channel Audit",body:"Understanding every touchpoint — digital and physical — where the brand appears, and the specific constraints of each."},{step:"02",title:"Visual Exploration",body:"Identity directions designed to be distinctive in the specific e-commerce category."},{step:"03",title:"System Build",body:"Complete identity system with specific guidance for digital channels, packaging, and social."},{step:"04",title:"Application Templates",body:"Ready-to-use templates for the most common recurring applications: email headers, social posts, product page assets."}],featuredProjectIds:["care-to-beauty","floema"],faqs:[{q:"Do you design product packaging?",a:"We provide packaging design direction — the visual brief and brand guidelines that a specialist packaging studio or manufacturer can execute. For brands with significant packaging needs, we can co-produce with specialist packaging partners."}],heroImage:"https://cdn.sanity.io/images/zksivtxz/production/7a93219d8ac5acd8c5751d81302f153f62499d84-1180x720.jpg",parentService:"brand-identity",industryName:"E-commerce"}];function r(e){return i.find(t=>t.slug===e)}const s=i.filter(e=>!e.parentService),d=i.filter(e=>!!e.parentService);function c(e){return e.featuredProjectIds.map(t=>n.find(a=>a.id===t)).filter(Boolean)}export{c as a,s as c,r as g,d as i,i as s};
